const uid=()=>crypto.randomUUID(),now=()=>new Date().toISOString(),number=p=>p+"-"+Date.now().toString(36).toUpperCase()+"-"+Math.floor(Math.random()*900+100);
const reply=(x,status=200,h={})=>new Response(JSON.stringify(x),{status,headers:{"content-type":"application/json;charset=utf-8","cache-control":"no-store","x-content-type-options":"nosniff",...h}});
