 if(!allowed(u,"jobs",false)&&!allowed(u,"attendance",false)&&!allowed(u,"purchases",false)&&!allowed(u,"staff",false))return fail("Access denied",403);
 let profiles=(await db.prepare("SELECT * FROM records WHERE module='staff' ORDER BY created_at DESC").all()).results||[];
 if(u.role==="Worker")profiles=profiles.filter(x=>String(JSON.parse(x.data).email||"").toLowerCase()===u.email.toLowerCase());
 const staff=profiles.map(x=>({id:x.id,name:JSON.parse(x.data).name||"",role:JSON.parse(x.data).role||"",status:JSON.parse(x.data).status||""})).filter(x=>x.status!=="Former");
 const inventory=allowed(u,"purchases",false)?((await db.prepare("SELECT * FROM records WHERE module='inventory'").all()).results||[]).map(x=>({id:x.id,sku:JSON.parse(x.data).sku||"",name:JSON.parse(x.data).name||"",cost:Number(JSON.parse(x.data).cost||0)})):[];
