if(path==="/api/update"&&method==="POST"){
 const b=await body(req.clone());
 if(b.module==="purchases"){
  if(!allowed(u,"purchases",true)||u.role==="Worker")return fail("No purchase editing permission",403);
  const current=await one(db,"purchases",b.id);
  if(!current)return fail("Purchase order not found",404);
  if(current.data.status!=="Requested")return fail("Only requested purchase orders can be edited",403);
  const updated=await phase1PurchaseData(db,{...current.data,...b.data});
  updated.status="Requested";
  await db.prepare("UPDATE records SET data=?,updated_at=? WHERE module='purchases' AND id=?").bind(JSON.stringify(updated),now(),b.id).run();
  await log(db,u,"UPDATE","purchases",b.id,{before:current.data,after:updated});
  return reply({ok:true});
 }
}
