  const password=String(b.password||"");if(password.length<12)return fail("Temporary password needs at least 12 characters");
  if(target.role==="Owner")return fail("Owner must use Change Password instead",403);
  const salt=uid(),hash=await hashPass(password,salt);
  await db.prepare("UPDATE users SET password_hash=?,salt=? WHERE id=?").bind(hash,salt,target.id).run();
  await db.prepare("DELETE FROM sessions WHERE user_id=?").bind(target.id).run();
  await log(db,u,"RESET_PASSWORD","users",target.id,{});return reply({ok:true});
